CREATE EXTENSION IF NOT EXISTS http WITH SCHEMA extensions;
DO $$ BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.reports;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$
DECLARE
  f text;
  body text;
  st int;
  files text[] := ARRAY['20260501011939_cbadc19b-c54f-4d83-bfa2-815730ce2207.sql','20260501012236_2d37c614-4d3f-406b-91a1-5c7eac6e0991.sql','20260502003908_c7fc8268-2f22-4bbf-8cdf-269c1f4d9dc3.sql','20260503004349_a8199cf2-382a-4ae1-8021-350360cb9f66.sql','20260604211032_c1e9e3ad-1b81-4c1d-b033-69316056f2cc.sql','20260605144947_a32552a6-375b-415f-9249-e8f77a10a8d3.sql','20260606003513_aba73e0d-643b-4b10-af5f-d34f43863dd2.sql','20260607003334_29abf9dd-a595-42c0-97d5-de24e7620614.sql','20260609002609_4d0c8413-f7d2-4f1b-b651-ee686f6f78f9.sql','20260609005718_7ff6d833-6dd3-4af2-9def-b0d30b47d802.sql','20260701122047_2d276ee7-1017-4c94-b27f-327d2886be66.sql','20260701122211_350a7e6b-b87d-4672-ac05-1c2c9cdbb17d.sql','20260701124324_38424397-7cac-4f64-8b53-451d4f2ee2c8.sql','20260702002315_9b23a008-1508-4d73-9e91-31a88c602ba8.sql','20260703004437_cbce14ec-bfa9-4903-b287-a7fbf70813c6.sql','20260706003731_81843e3d-4db8-4251-9d3a-6355440422ef.sql','20260706004257_26576304-7a9d-4a63-9298-4cab52a71362.sql','20260801130657_d7e682f2-0986-453b-b2c4-4824e1132580.sql','20260801132455_5804587f-1ecb-4991-8cc4-8f21bd1e9187.sql','20260801132515_dcb8e2df-8ff7-4bc1-86f3-f73897fee8ad.sql','20260801132607_02e043f5-93c9-4451-a8c6-2c6599ea0c9a.sql','20260801132936_7a6a579c-fabc-43ec-9235-bdb280be017d.sql','20260801132959_879480a7-6cd1-4c44-88e7-00c92051286d.sql','20260802142437_daeeeb7d-7ab8-43c8-86a0-641a85fd08bc.sql','20260803010509_56ae7d77-938e-4f9c-b42c-88ce583956ac.sql','20260804001908_4341f7fe-8bec-4615-b5f5-7bda22d29e27.sql','20260804001930_429065c8-7543-4a52-bb18-b03117fc2aa5.sql','20260804002010_e9d4faa7-cf2e-4b01-b832-753d23c4f0af.sql'];
BEGIN
  FOREACH f IN ARRAY files LOOP
    SELECT status, content INTO st, body FROM extensions.http_get('https://raw.githubusercontent.com/Davidweverson/flash-chat-amigos/6f0050c96ab9154d0bcd9430e306b073ffc97db7/supabase/migrations/' || f);
    IF st <> 200 THEN RAISE EXCEPTION 'fetch % failed: %', f, st; END IF;
    BEGIN
      EXECUTE body;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'migration % failed: %', f, SQLERRM;
    END;
  END LOOP;
END $$;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO authenticated;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO anon;
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;